<main class="content"><div class="page-actions"><a href="<?=url('/admin/usuarios')?>">← Volver a usuarios</a><a class="primary" href="<?=url('/admin/usuarios/formulario?id='.$user['id'])?>">Editar usuario</a></div><section class="panel record-view"><div class="record-hero"><span class="profile-avatar"><?=e(substr($user['first_name'],0,1).substr($user['last_name'],0,1))?></span><div><span class="eyebrow">PERFIL DE USUARIO</span><h2><?=e($user['first_name'].' '.$user['last_name'])?></h2><p><?=e($user['email'])?></p></div><span class="status <?=$user['active']?'on':'off'?>"><?=$user['active']?'Activo':'Inactivo'?></span></div><div class="detail-grid"><div><small>Rol</small><b><?=e(ucfirst($user['role']))?></b></div><div><small>Asignatura</small><b><?=e($user['subject']??'Sin asignatura')?></b></div><div><small>Teléfono</small><b><?=e($user['phone']?:'No informado')?></b></div><div><small>Acceso a tests</small><b><?=$user['test_enabled']?'Habilitado':'No habilitado'?></b></div><div><small>Acceso a tabuladores</small><b><?=$user['tabulator_enabled']?'Habilitado':'No habilitado'?></b></div><div><small>Creado</small><b><?=e($user['created_at'])?></b></div></div><form class="delete-zone" method="post" action="<?=url('/admin/usuarios/eliminar')?>" onsubmit="return confirm('¿Eliminar definitivamente este usuario?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$user['id']?>"><div><b>Eliminar cuenta</b><p>Esta acción elimina el registro del usuario.</p></div><button class="danger">Eliminar usuario</button></form></section></main>
